package io.knowledgebrain.space;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
@ConditionalOnProperty(name="brain.space.group-membership.enabled",havingValue="true")
class GroupMembershipController {
 record Page<T>(List<T> items,UUID nextAfter){}
 record History<T>(List<T> items,Long nextBefore){}
 private final GroupMembershipStore store;private final IdentityPrincipalClient identity;private final String origin;
 GroupMembershipController(GroupMembershipStore store,IdentityPrincipalClient identity,@Value("${brain.space.group-membership.browser-origin}")String origin){this.store=store;this.identity=identity;this.origin=origin;}
 private UUID actor(HttpServletRequest r){var p=identity.resolve(GroupBrowserRequest.token(r),GroupBrowserRequest.parent(r));if(!"REGISTERED".equals(p.kind()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Registered account required");return p.principalId();}
 private String trace(HttpServletRequest r){return GroupBrowserRequest.parent(r).substring(3,35);}
 private <T> ResponseEntity<T> response(T value){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("Referrer-Policy","no-referrer").body(value);}
 private ResponseEntity<GroupMembershipStore.Member> member(GroupMembershipStore.Member m){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"gm"+m.version()+"\"").body(m);}
 @GetMapping("/api/groups/{groupId}/membership") ResponseEntity<GroupMembershipStore.Member> self(@PathVariable String groupId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.read(r,Set.of());return member(store.self(GroupBrowserRequest.id(groupId),who));}
 @GetMapping("/api/groups/{groupId}/members") ResponseEntity<Page<GroupMembershipStore.Member>> members(@PathVariable String groupId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.read(r,Set.of("after","limit"));int limit=GroupBrowserRequest.limit(r,100,20);var rows=store.members(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.after(r),limit);var page=rows.subList(0,Math.min(limit,rows.size()));return response(new Page<>(page,rows.size()>limit?page.getLast().principalId():null));}
 @PutMapping("/api/groups/{groupId}/members/{principalId}") ResponseEntity<GroupMembershipStore.Member> change(@PathVariable String groupId,@PathVariable String principalId,HttpServletRequest r)throws IOException{var who=actor(r);var body=GroupBrowserRequest.write(r,origin,Set.of("role"));return member(store.change(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.id(principalId),GroupBrowserRequest.match(r,"gm"),body.get("role").asString(),trace(r)));}
 @DeleteMapping("/api/groups/{groupId}/members/{principalId}") ResponseEntity<GroupMembershipStore.Member> remove(@PathVariable String groupId,@PathVariable String principalId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.write(r,origin,Set.of());return member(store.retire(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.id(principalId),GroupBrowserRequest.match(r,"gm"),false,trace(r)));}
 @PostMapping("/api/groups/{groupId}/leave") ResponseEntity<GroupMembershipStore.Member> leave(@PathVariable String groupId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.write(r,origin,Set.of());return member(store.retire(GroupBrowserRequest.id(groupId),who,who,GroupBrowserRequest.match(r,"gm"),true,trace(r)));}
 @GetMapping("/api/groups/{groupId}/members/{principalId}/revisions") ResponseEntity<History<GroupMembershipStore.MemberRevision>> memberHistory(@PathVariable String groupId,@PathVariable String principalId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.read(r,Set.of("before","limit"));int limit=GroupBrowserRequest.limit(r,10,10);var rows=store.memberHistory(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.id(principalId),GroupBrowserRequest.before(r),limit);var page=rows.subList(0,Math.min(limit,rows.size()));return response(new History<>(page,rows.size()>limit?page.getLast().version():null));}
 @PostMapping("/api/groups/{groupId}/invitations") ResponseEntity<GroupMembershipStore.Issued> issue(@PathVariable String groupId,HttpServletRequest r)throws IOException{var who=actor(r);var json=GroupBrowserRequest.write(r,origin,Set.of("role"));return response(store.issue(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.key(r),json.get("role").asString(),trace(r)));}
 @GetMapping("/api/groups/{groupId}/invitations") ResponseEntity<Page<GroupMembershipStore.Invitation>> invitations(@PathVariable String groupId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.read(r,Set.of("after","limit"));int limit=GroupBrowserRequest.limit(r,100,20);var rows=store.invitations(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.after(r),limit);var page=rows.subList(0,Math.min(limit,rows.size()));return response(new Page<>(page,rows.size()>limit?page.getLast().invitationId():null));}
 @PostMapping("/api/groups/{groupId}/invitations/{invitationId}/revoke") ResponseEntity<GroupMembershipStore.Invitation> revoke(@PathVariable String groupId,@PathVariable String invitationId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.write(r,origin,Set.of());var i=store.revoke(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.id(invitationId),GroupBrowserRequest.match(r,"gi"),trace(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"gi"+i.version()+"\"").body(i);}
 @GetMapping("/api/groups/{groupId}/invitations/{invitationId}/revisions") ResponseEntity<History<GroupMembershipStore.InvitationRevision>> invitationHistory(@PathVariable String groupId,@PathVariable String invitationId,HttpServletRequest r)throws IOException{var who=actor(r);GroupBrowserRequest.read(r,Set.of("before","limit"));int limit=GroupBrowserRequest.limit(r,10,10);var rows=store.invitationHistory(GroupBrowserRequest.id(groupId),who,GroupBrowserRequest.id(invitationId),GroupBrowserRequest.before(r),limit);var page=rows.subList(0,Math.min(limit,rows.size()));return response(new History<>(page,rows.size()>limit?page.getLast().version():null));}
 @PostMapping("/api/group-invitations/accept") ResponseEntity<GroupMembershipStore.Member> accept(HttpServletRequest r)throws IOException{var who=actor(r);var json=GroupBrowserRequest.write(r,origin,Set.of("code"));return member(store.accept(who,json.get("code").asString(),trace(r)));}
}
